 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    top = [(c, grid[0][c]) for c in range(w) if grid[0][c] != 0]

    for c, color in top:
        # A matching marker on either side sets the end of this vertical ray.
        endpoints = [r for r in range(1, h) if grid[r][0] == color or grid[r][w - 1] == color]
        end = max(endpoints) if endpoints else h - 1
        for r in range(1, end + 1):
            if out[r][c] == 0:
                out[r][c] = color
        # Side marker(s) project horizontally back to the matching top-row color.
        for r in range(1, h):
            if grid[r][0] == color:
                for x in range(1, c + 1):
                    if out[r][x] == 0:
                        out[r][x] = color
            if grid[r][w - 1] == color:
                for x in range(c, w - 1):
                    if out[r][x] == 0:
                        out[r][x] = color
    return out
